def min_taps_brute(n, ranges):
    taps = [(max(0, i - ranges[i]), i + ranges[i]) for i in range(n + 1)]
    best = [float('inf')]

    def covers_all(chosen):
        covered = [False] * (n + 1)
        for l, r in chosen:
            for x in range(max(0, l), min(n, r) + 1):
                covered[x] = True
        return all(covered)

    def backtrack(i, chosen):
        if i == len(taps):
            if covers_all(chosen):                     # check full coverage directly
                best[0] = min(best[0], len(chosen))
            return
        backtrack(i + 1, chosen)                          # skip this tap
        backtrack(i + 1, chosen + [taps[i]])               # open this tap

    backtrack(0, [])
    return best[0] if best[0] != float('inf') else -1

