def min_taps(n, ranges):
    max_reach = [0] * (n + 1)
    for i in range(n + 1):
        l = max(0, i - ranges[i])
        max_reach[l] = max(max_reach[l], i + ranges[i])       # farthest reach starting at l

    taps = 0
    cur_end = next_end = 0
    for i in range(n + 1):
        if i > next_end:
            return -1                                            # a gap that cannot be bridged
        if i > cur_end:
            taps += 1                                             # need one more tap
            cur_end = next_end
        next_end = max(next_end, max_reach[i])
    return taps

