        for (int i = 0; i <= n; i++) {
            int l = Math.max(0, i - ranges[i]);
            maxReach[l] = Math.max(maxReach[l], i + ranges[i]);      // farthest reach starting at l
        }
        int taps = 0, curEnd = 0, nextEnd = 0;
        for (int i = 0; i <= n; i++) {
